CREATE TABLE Shops (Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), Name nvarchar(160) NOT NULL, Slug nvarchar(180) NOT NULL UNIQUE, OwnerUserId nvarchar(450) NOT NULL, Description nvarchar(1000) NULL, Status nvarchar(24) NOT NULL DEFAULT 'Pending', CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE ShopBranches (Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), ShopId uniqueidentifier NOT NULL REFERENCES Shops(Id), Name nvarchar(160) NOT NULL, Address nvarchar(500) NOT NULL, IsActive bit NOT NULL DEFAULT 1);
CREATE TABLE Categories (Id int IDENTITY PRIMARY KEY, ParentId int NULL REFERENCES Categories(Id), Name nvarchar(100) NOT NULL, IsActive bit NOT NULL DEFAULT 1);
CREATE TABLE Products (Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), ShopId uniqueidentifier NOT NULL REFERENCES Shops(Id), CategoryId int NOT NULL REFERENCES Categories(Id), Name nvarchar(180) NOT NULL, Description nvarchar(2000) NULL, IsActive bit NOT NULL DEFAULT 1);
CREATE TABLE ProductVariants (Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), ProductId uniqueidentifier NOT NULL REFERENCES Products(Id), Name nvarchar(100) NOT NULL, Unit nvarchar(20) NOT NULL, Price decimal(12,2) NOT NULL CHECK (Price >= 0), IsActive bit NOT NULL DEFAULT 1);
CREATE TABLE Inventory (BranchId uniqueidentifier NOT NULL REFERENCES ShopBranches(Id), VariantId uniqueidentifier NOT NULL REFERENCES ProductVariants(Id), Quantity decimal(12,3) NOT NULL DEFAULT 0 CHECK (Quantity >= 0), LowStockThreshold decimal(12,3) NOT NULL DEFAULT 0, CONSTRAINT PK_Inventory PRIMARY KEY (BranchId,VariantId));
CREATE TABLE StockMovements (Id bigint IDENTITY PRIMARY KEY, BranchId uniqueidentifier NOT NULL REFERENCES ShopBranches(Id), VariantId uniqueidentifier NOT NULL REFERENCES ProductVariants(Id), QuantityDelta decimal(12,3) NOT NULL, Reason nvarchar(40) NOT NULL, CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), CreatedBy nvarchar(450) NULL);
CREATE TABLE Addresses (Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), UserId nvarchar(450) NOT NULL, Label nvarchar(40) NOT NULL, Recipient nvarchar(160) NOT NULL, Phone nvarchar(30) NOT NULL, AddressText nvarchar(500) NOT NULL, PostalCode nvarchar(20) NOT NULL, IsDefault bit NOT NULL DEFAULT 0);
CREATE TABLE Orders (Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), OrderNumber nvarchar(32) NOT NULL UNIQUE, CustomerUserId nvarchar(450) NOT NULL, AddressSnapshot nvarchar(1000) NOT NULL, Subtotal decimal(12,2) NOT NULL, DeliveryFee decimal(12,2) NOT NULL DEFAULT 0, Total decimal(12,2) NOT NULL, Status nvarchar(24) NOT NULL DEFAULT 'Pending', PaymentStatus nvarchar(24) NOT NULL DEFAULT 'Pending', CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE ShopOrders (Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), OrderId uniqueidentifier NOT NULL REFERENCES Orders(Id), ShopId uniqueidentifier NOT NULL REFERENCES Shops(Id), BranchId uniqueidentifier NULL REFERENCES ShopBranches(Id), Status nvarchar(24) NOT NULL DEFAULT 'Pending', Subtotal decimal(12,2) NOT NULL);
CREATE TABLE OrderItems (Id bigint IDENTITY PRIMARY KEY, ShopOrderId uniqueidentifier NOT NULL REFERENCES ShopOrders(Id), VariantId uniqueidentifier NULL REFERENCES ProductVariants(Id), ProductNameSnapshot nvarchar(180) NOT NULL, VariantSnapshot nvarchar(100) NOT NULL, UnitSnapshot nvarchar(20) NOT NULL, UnitPrice decimal(12,2) NOT NULL, Quantity decimal(12,3) NOT NULL, LineTotal decimal(12,2) NOT NULL);
CREATE TABLE OrderStatusHistory (Id bigint IDENTITY PRIMARY KEY, ShopOrderId uniqueidentifier NOT NULL REFERENCES ShopOrders(Id), Status nvarchar(24) NOT NULL, Note nvarchar(500) NULL, CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Payments (Id uniqueidentifier NOT NULL PRIMARY KEY DEFAULT NEWID(), OrderId uniqueidentifier NOT NULL REFERENCES Orders(Id), Method nvarchar(24) NOT NULL, Status nvarchar(24) NOT NULL, Amount decimal(12,2) NOT NULL, ProviderReference nvarchar(160) NULL, CreatedUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
